describe('Profile Update Confirmation Message', () => {
  beforeEach(() => {
    cy.visit('/profile');
  });

  it('should display confirmation message after successful profile update', () => {
    // Intercept the API call to update profile
    cy.intercept('POST', '/api/profile/update').as('updateProfile');

    // Fill in new profile details
    cy.get('[data-testid="first-name-input"]').type('John');
    cy.get('[data-testid="last-name-input"]').type('Doe');
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="password-input"]').type('newpassword123');

    // Submit the form
    cy.get('[data-testid="update-profile-button"]').click();

    // Wait for the API call to complete
    cy.wait('@updateProfile').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify confirmation message appears
    cy.get('[data-testid="confirmation-message"]').should('be.visible');
    cy.get('[data-testid="confirmation-message"]').should('contain', 'Profile updated successfully');

    // Verify success toast appears
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Profile updated');

    // Verify success toast has close button
    cy.get('[data-testid="success-toast-close-btn"]').should('be.visible');

    // Verify success toast disappears after clicking close
    cy.get('[data-testid="success-toast-close-btn"]').click();
    cy.get('[data-testid="success-toast"]').should('not.exist');
  });

  it('should not display confirmation message on failed profile update', () => {
    // Intercept the API call to update profile
    cy.intercept('POST', '/api/profile/update', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('updateProfileError');

    // Fill in new profile details
    cy.get('[data-testid="first-name-input"]').type('Jane');
    cy.get('[data-testid="last-name-input"]').type('Smith');
    cy.get('[data-testid="email-input"]').type('jane.smith@example.com');
    cy.get('[data-testid="password-input"]').type('newpassword123');

    // Submit the form
    cy.get('[data-testid="update-profile-button"]').click();

    // Wait for the API call to complete
    cy.wait('@updateProfileError');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Profile update failed');

    // Verify error toast appears
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Profile update failed');

    // Verify error toast has close button
    cy.get('[data-testid="error-toast-close-btn"]').should('be.visible');

    // Verify error toast disappears after clicking close
    cy.get('[data-testid="error-toast-close-btn"]').click();
    cy.get('[data-testid="error-toast"]').should('not.exist');
  });
});
